-- Preserve the typed meaning of Story 2.1 Templates, without selecting a source.
UPDATE "procedure_version" SET "inclusion_rule" = CASE "template_id"
  WHEN 'P-1' THEN '{"schemaVersion":1,"all":[{"column":"employment_status","kind":"text","operator":"eq","value":"Terminated"},{"column":"termination_effective_date","kind":"within-period"}]}'::jsonb
  WHEN 'P-2' THEN '{"schemaVersion":1,"all":[{"column":"status","kind":"text","operator":"eq","value":"Active"}]}'::jsonb
  WHEN 'P-3' THEN '{"schemaVersion":1,"all":[{"column":"currency","kind":"text","operator":"eq","value":"USD"},{"column":"amount","kind":"decimal","operator":"gte","value":"100000"},{"column":"processed_time","kind":"within-period"}]}'::jsonb
  ELSE '{"schemaVersion":1,"all":[]}'::jsonb END;--> statement-breakpoint
